#pragma once

#include <stddef.h>
#include <stdint.h>
#include <string.h>

// AI: below section was generated by an AI
// Certificate validity dates, checked after each TLS handshake: the pinned mbedTLS build lacks
// MBEDTLS_HAVE_TIME_DATE and skips them. Pure templates over the mbedTLS field names; host-tested.
#ifndef KITE_BUILD_EPOCH
#define KITE_BUILD_EPOCH 0 // tools/kite_version.py sets it from SOURCE_DATE_EPOCH or the commit time
#endif

namespace KiteWindCert {
constexpr int64_t CLOCK_FLOOR_UTC = 1767225600; // 2026-01-01T00:00:00Z, used when no build epoch is known
constexpr int64_t BUILD_EPOCH_UTC = KITE_BUILD_EPOCH;
// No valid clock predates this build's source; bounds clock rollback per release without manual bumps.
constexpr int64_t MIN_VALID_UTC = BUILD_EPOCH_UTC > CLOCK_FLOOR_UTC ? BUILD_EPOCH_UTC : CLOCK_FLOOR_UTC;
static_assert(MIN_VALID_UTC <= UINT32_MAX, "the clock floor must fit the 32-bit NTP time");
constexpr unsigned MAX_CHAIN = 4; // received certificates examined, leaf included

// Trust anchor: raw DER subject and notAfter of the compiled-in root.
struct Anchor {
  const unsigned char* subject;
  size_t subjectLength;
  int64_t notAfter;
};

inline int daysInMonth(int year, int month) {
  static const uint8_t DAYS[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
  bool leap = (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
  return month == 2 && leap ? 29 : DAYS[month - 1];
}

// Converts mbedtls_x509_time fields (UTC) to Unix seconds in 64 bits. False for fields outside the
// ranges mbedTLS accepts (year 1..9999, no leap second). Days from civil date: H. Hinnant,
// "chrono-Compatible Low-Level Date Algorithms" (days_from_civil).
template <class Time> bool mbedtlsTimeToEpoch(const Time& t, int64_t& out) {
  if (t.year < 1 || t.year > 9999 || t.mon < 1 || t.mon > 12 || t.day < 1 || t.day > daysInMonth(t.year, t.mon)
      || t.hour < 0 || t.hour > 23 || t.min < 0 || t.min > 59 || t.sec < 0 || t.sec > 59) return false;
  const int64_t y = t.year - (t.mon <= 2 ? 1 : 0); // years start in March
  const int64_t era = y / 400, yoe = y - era * 400;
  const int64_t doy = (153 * ((t.mon + 9) % 12) + 2) / 5 + t.day - 1;
  const int64_t days = era * 146097 + yoe * 365 + yoe / 4 - yoe / 100 + doy - 719468;
  out = days * 86400 + t.hour * 3600 + t.min * 60 + t.sec;
  return true;
}

// RFC 5280 4.1.2.5: valid from notBefore through notAfter, both inclusive (so notBefore > notAfter never
// passes). Fails closed below the clock floor.
inline bool certDatesValid(int64_t notBefore, int64_t notAfter, int64_t now) {
  return now >= MIN_VALID_UTC && notBefore <= now && now <= notAfter;
}

template <class Buf> bool sameName(const Buf& name, const unsigned char* raw, size_t length) {
  return name.p && raw && name.len == length && memcmp(name.p, raw, length) == 0;
}

// Walks the peer chain as received (leaf first, linked by next). Checks the leaf and each certificate
// that issued the previous one, skips unrelated extras, and stops at the certificate the anchor issued,
// so a stale cross-signed root behind it is ignored. Fails closed: no chain, clock below the floor or
// past the anchor, a bad or out-of-range date, or no anchor-issued certificate within MAX_CHAIN.
template <class Crt> bool chainDatesValid(const Crt* crt, int64_t now, const Anchor& anchor) {
  if (!crt || now < MIN_VALID_UTC || now > anchor.notAfter) return false;
  const Crt* previous = nullptr;
  for (unsigned seen = 0; crt && seen < MAX_CHAIN; crt = crt->next, ++seen) {
    // Takes the first later certificate whose subject matches by name; mbedTLS chose the path by signature.
    // Acceptable: the leaf is always checked, and a mismatch needs the key of a same-named expired intermediate.
    if (previous && !sameName(crt->subject_raw, previous->issuer_raw.p, previous->issuer_raw.len)) continue;
    int64_t from = 0, to = 0;
    if (!mbedtlsTimeToEpoch(crt->valid_from, from) || !mbedtlsTimeToEpoch(crt->valid_to, to)) return false;
    if (!certDatesValid(from, to, now)) return false;
    if (sameName(crt->issuer_raw, anchor.subject, anchor.subjectLength)) return true;
    previous = crt;
  }
  return false;
}

// Admission of one TLS session: admit() after each handshake, reset() on close. write() passes bytes
// to the session only while the current handshake is admitted, so a rejected peer receives none.
class SessionGate {
public:
  template <class Crt> bool admit(const Crt* chain, int64_t now, const Anchor& anchor) {
    _admitted = chainDatesValid(chain, now, anchor);
    return _admitted;
  }
  void reset() { _admitted = false; }
  bool admitted() const { return _admitted; }
  template <class Session> size_t write(Session& session, const uint8_t* data, size_t length) {
    return _admitted ? session.write(data, length) : 0;
  }

private:
  bool _admitted = false;
};
} // namespace KiteWindCert
